755→<!-- Redirect links and searches when in dual view mode -->
756→<script>
757→document.addEventListener("DOMContentLoaded", function () {
758→  if (!window.location.pathname.startsWith("/dual")) return;
759→
760→  function getTargetPanel() {
761→    const selected = document.querySelector('input[name="targetPanel"]:checked');
762→    return selected ? selected.value : "left";
763→  }
764→
765→  function loadInPanel(panel, path) {
766→    if (!path) return;
767→    const iframe = document.getElementById(`iframe-${panel}`);
768→    if (!iframe) return;
769→    const url = path.includes("?") ? path + "&embed=1" : path + "?embed=1";
770→    iframe.src = url;
771→    const inputBox = document.querySelector(`#panel-${panel} input`);
772→    if (inputBox) inputBox.value = path;
773→    console.log(`Loaded "${url}" into panel "${panel}"`);
774→  }
775→  
776→  document.querySelectorAll(".dual-aware a[href^='/'], a.dual-aware[href^='/']").forEach(link => {
777→    link.addEventListener("click", function (e) {
778→      e.preventDefault();
779→      const path = this.getAttribute("href");
780→      loadInPanel(getTargetPanel(), path);
781→    });
782→  });
783→
784→  const idForm = document.getElementById("idsearchForm");
