790→
791→      let path = null;
792→
793→      if (/^\d+$/.test(input)) {
794→        path = "/go_to/" + encodeURIComponent(input);
795→      } else if (/^((\d+|end)(-(\d+|end))?\s*)+(open|solved|yes|no)?$/i.test(input)) {
796→        const parts = input.split(/\s+/).filter(Boolean);
797→        path = "/range/" + parts.map(encodeURIComponent).join("/");
798→      } else {
799→        alert("Invalid input format.");
800→        return;
801→      }
802→
803→      loadInPanel(getTargetPanel(), path);
804→    });
805→  }
806→
807→  const searchForm = document.getElementById("searchForm");
808→  if (searchForm) {
809→    searchForm.addEventListener("submit", function (e) {
810→      e.preventDefault();
811→      const input = searchForm.querySelector(".searchTerm").value.trim();
812→      if (!input) return;
813→
814→      const path = "/search/" + encodeURIComponent(input);
815→      loadInPanel(getTargetPanel(), path);
816→    });
817→  }
818→});
